effect.shader:
vec4 sampleTex(sampler2D t, vec2 uv){ return texture2DCv(t, uv); }
mat2 rot2(float a){ float s=sin(a), c=cos(a); return mat2(c,-s,s,c); }
vec2 mirror(vec2 uv){ return abs(fract(uv*0.5+0.5)*2.0-1.0); }
float envelope(float t, float freq, float damp, float dur){
if(t < 0.0) return 0.0;
if(t > dur) return 0.0;
float w = 6.28318530718 * freq;
return exp(-damp * t) * sin(w * t);
}
float repeatTime(float time, float trig, bool en, float period){
if(!en) return time - trig;
float tau = time - trig;
if(period <= 0.0) return tau;
float m = floor(tau / period);
float local = tau - m * period;
return local;
}
void main(){
vec2 uv = acScreenNorm;
float tauBase = repeatTime(acTime, triggerTime, enableRepeat, repeatPeriod);
float env = envelope(tauBase, frequency, damping, duration) * strength;
float ang = radians(angle);
vec2 dir = vec2(cos(ang), sin(ang));
vec2 posPx = dir * ampPos * env;
float rotDeg = ampRot * env;
float scl = 1.0 + ampScale * env;
vec2 texSize = inputImg.size;
vec2 posUV = posPx / max(texSize, vec2(1.0));
vec2 pivot = vec2(pivotX, pivotY);
float autoS = 1.0 + expand;
float rot = radians(rotDeg);
vec2 rel = uv - pivot;
rel -= posUV;
rel = rot2(-rot) * rel;
rel /= max(scl*autoS, 1e-6);
vec2 srcUV = pivot + rel;
vec4 col;
if(mirrorEdges){
col = sampleTex(inputImg.texture, mirror(srcUV));
} else {
if(any(lessThan(srcUV, vec2(0.0))) || any(greaterThan(srcUV, vec2(1.0)))){
col = vec4(0.0);
} else {
col = sampleTex(inputImg.texture, srcUV);
}
}
gl_FragColor = col;
}
